// Webhook providers may retry the same event. Validate the minimum shape and
// keep a short-lived idempotency key so one message cannot create two strikes.
const now = Date.now();
const store = $getWorkflowStaticData('global');
store.recentEvents ??= {};

const out = [];
for (const item of $input.all()) {
  const b = item.json.body;
  const validBody = b && typeof b === 'object' && !Array.isArray(b);
  const isKnownEvent = validBody && (
    typeof b.notification === 'string' ||
    (b.isGroup === true && typeof b.text?.message === 'string')
  );

  const ttlMs = Math.max(1, Number(item.json.duplicateWindowSeconds || 300)) * 1000;
  for (const [key, seenAt] of Object.entries(store.recentEvents)) {
    if (now - Number(seenAt) > ttlMs) delete store.recentEvents[key];
  }

  const rawKey = validBody
    ? (b.messageId || [b.notification, b.phone, b.group_jid, b.participantPhone, b.momment].filter(Boolean).join(':'))
    : '';
  const eventKey = String(rawKey || '').trim();
  const duplicate = Boolean(eventKey && store.recentEvents[eventKey]);
  if (eventKey && !duplicate) store.recentEvents[eventKey] = now;

  out.push({
    json: {
      ...item.json,
      processEvent: isKnownEvent && !duplicate,
      validationStatus: !isKnownEvent ? 'invalid_event' : duplicate ? 'duplicate_event' : 'accepted',
      eventKey,
    },
  });
}
return out;

// Detect disallowed URLs while avoiding common allowlist bypasses.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  const text = String(b.text?.message || '');
  const sender = String(b.participantPhone || b.senderPhone || '').replace(/\D/g, '');

  const admins = String(item.json.adminPhones || '')
    .split(',').map((p) => p.replace(/\D/g, '')).filter(Boolean);
  const allowed = String(item.json.allowedDomains || '')
    .split(',')
    .map((d) => d.trim().toLowerCase().replace(/^www\./, ''))
    .filter(Boolean);

  const urls = text.match(/(?:https?:\/\/|www\.)[^\s<>()]+|chat\.whatsapp\.com\/[^\s<>()]+/gi) || [];
  const cleaned = urls.map((u) => u.replace(/[.,!?;:)\]}]+$/g, ''));
  const offending = cleaned.filter((url) => {
    const candidate = /^https?:\/\//i.test(url) ? url : `https://${url}`;
    try {
      const host = new URL(candidate).hostname.toLowerCase().replace(/^www\./, '');
      return !allowed.some((domain) => host === domain || host.endsWith(`.${domain}`));
    } catch {
      return true;
    }
  });

  const isAdmin = admins.includes(sender);
  out.push({
    json: {
      shouldModerate: offending.length > 0 && !isAdmin,
      groupId: b.phone || b.group_jid,
      messageId: b.messageId,
      offender: sender,
      offendingUrls: offending,
      decision: isAdmin ? 'admin_bypass' : offending.length ? 'blocked_domain' : 'allowed',
      strikeWindowMinutes: item.json.strikeWindowMinutes,
      strikeLimit: item.json.strikeLimit,
      removeRepeatOffenders: item.json.removeRepeatOffenders,
    },
  });
}
return out;

// Keep a per-group, per-sender strike window in workflow static data.
// Static data persists when the workflow is active; manual test runs may not persist it.
const now = Date.now();
const store = $getWorkflowStaticData('global');
store.moderationStrikes ??= {};

return $input.all().map((item) => {
  const key = `${item.json.groupId}:${item.json.offender}`;
  const windowMs = Math.max(1, Number(item.json.strikeWindowMinutes || 1440)) * 60 * 1000;
  const previous = Array.isArray(store.moderationStrikes[key]) ? store.moderationStrikes[key] : [];
  const active = previous.map(Number).filter((time) => now - time <= windowMs);
  active.push(now);
  store.moderationStrikes[key] = active;

  const strikeLimit = Math.max(1, Number(item.json.strikeLimit || 3));
  return {
    json: {
      ...item.json,
      strikeCount: active.length,
      strikeLimit,
      removeParticipant: item.json.removeRepeatOffenders === true && active.length >= strikeLimit,
    },
  };
});
